    const win=wantYes===yes; return {status:win?'WON':'LOSS',pnl:money(win?stake*(odd-1):-stake)};
  }
  if(fam==='MONEYLINE'){
    const actual=h>a?'HOME':h<a?'AWAY':'DRAW';
    const normalized=side.replace('_WIN','');
    const win=normalized===actual; return {status:win?'WON':'LOSS',pnl:money(win?stake*(odd-1):-stake)};
  }
  if(fam==='DOUBLE_CHANCE'){
    const win=(['1X','ONE_X'].includes(side)&&h>=a)||(['X2','X_TWO'].includes(side)&&a>=h)||(['12','ONE_TWO'].includes(side)&&h!==a);
    return {status:win?'WON':'LOSS',pnl:money(win?stake*(odd-1):-stake)};
  }
  if(fam==='GOALS'&&fin(line))return settleGoals(side,Number(line),h,a,odd,stake);
  if(fam==='ASIAN_HANDICAP'&&fin(line))return settleAsian(side,Number(line),h,a,odd,stake);
  return null;
}

const openRes=await req.call(this,{
  method:'GET',
  url:`${SUPABASE_URL.replace(/\/$/,'')}/rest/v1/sr_fusion_engine_picks?settlement_status=eq.OPEN&select=*&order=kickoff.asc`,
  headers:sbHeaders,json:true
});
if(!openRes.ok) return [{json:{diagnostic:true,settlementRun:true,error:'OPEN_ROWS_QUERY_FAILED',httpStatus:openRes.status||0,detail:openRes.error||null}}];

const rows=Array.isArray(openRes.body)?openRes.body:[];

const out=[];
let settled=0,repliesReady=0,providerErrors=0,notFinal=0,invalidScore=0,unsupported=0,patchErrors=0;
for(const p of rows){
  const fid=Number(p.fixture_id);
  const fx=await req.call(this,{
    method:'GET',url:`${API_BASE.replace(/\/$/,'')}/fixtures/${fid}`,
    headers:{'X-API-Key':API_KEY,'x-api-key':API_KEY,Authorization:`Bearer ${API_KEY}`,Accept:'application/json'},json:true
  });
  await sleep(7000);
  if(!fx.ok){
    providerErrors++;
    out.push({json:{diagnostic:true,settlementRun:true,pick_id:p.id,fixture_id:fid,home_team:p.home_team,away_team:p.away_team,settled:false,reason:'PROVIDER_ERROR',httpStatus:fx.status||0}});
    continue;
  }
  const f=unwrap(fx.body)||{};
  const status=String(typeof f.status==='string'?f.status:(f.status?.short??f.status?.name??f.status_code??'')).trim().toUpperCase();
  if(['POSTPONED','CANCELLED','CANCELED','ABANDONED'].includes(status)){
    const patch=await req.call(this,{method:'PATCH',url:`${SUPABASE_URL}/rest/v1/sr_fusion_engine_picks?id=eq.${p.id}`,
      headers:{...sbHeaders,Prefer:'return=minimal'},body:{settlement_status:'VOID',pnl:0,return_amount:Number(p.stake||100),settled_at:new Date().toISOString(),settlement_note:'Provider status '+status,settlement_reply_status:(Number(p.telegram_message_id)>0?'PENDING':'NOT_APPLICABLE')},json:true});
    if(!patch.ok){patchErrors++;continue;}
    settled++;
    const ready=!!p.telegram_message_id; if(ready)repliesReady++;
    out.push({json:{settlementRun:true,settled:true,pick_id:p.id,fixture_id:fid,status:'VOID',pnl:0,telegram_message_id:p.telegram_message_id||null,replyReady:ready,
      reply_text:'⚪ VOID'}});
    continue;
  }
  const finalStatuses=new Set(['FINISHED','FT','AET','AFTER_EXTRA_TIME','FULL_TIME']);
  if(!finalStatuses.has(status)){
    notFinal++;
    out.push({json:{diagnostic:true,settlementRun:true,pick_id:p.id,fixture_id:fid,home_team:p.home_team,away_team:p.away_team,provider_status:status||null,settled:false,reason:'NOT_FINAL'}});
    continue;
  }
  const h=num(f?.goals?.home??f?.score?.home??f?.home_score);
  const a=num(f?.goals?.away??f?.score?.away??f?.away_score);
  if(!fin(h)||!fin(a)){
    invalidScore++;
    out.push({json:{diagnostic:true,settlementRun:true,pick_id:p.id,fixture_id:fid,settled:false,reason:'FINAL_WITHOUT_SCORE',provider_status:status}});
    continue;
  }
  const r=settlePick(p,Number(h),Number(a));
  if(!r){
    unsupported++;
    out.push({json:{diagnostic:true,settlementRun:true,pick_id:p.id,fixture_id:fid,settled:false,reason:'UNSUPPORTED_MARKET',market_family:p.market_family,side:p.side,line:p.line}});
    continue;
  }
  const stake=Number(p.stake||100), ret=money(stake+r.pnl);
  const patchBody={settlement_status:r.status,home_score:Number(h),away_score:Number(a),settled_at:new Date().toISOString(),pnl:r.pnl,return_amount:ret,settlement_note:`${r.status} · FT ${h}:${a}`,settlement_reply_status:(Number(p.telegram_message_id)>0?'PENDING':'NOT_APPLICABLE')};
  const patch=await req.call(this,{method:'PATCH',url:`${SUPABASE_URL}/rest/v1/sr_fusion_engine_picks?id=eq.${p.id}`,
    headers:{...sbHeaders,Prefer:'return=minimal'},body:patchBody,json:true});
  if(!patch.ok){
    patchErrors++;
    out.push({json:{diagnostic:true,settlementRun:true,pick_id:p.id,fixture_id:fid,settled:false,reason:'DB_PATCH_FAILED',httpStatus:patch.status||0}});
    continue;
  }
  settled++;
  const ready=Number(p.telegram_message_id)>0; if(ready)repliesReady++;
  const label=r.status==='WON'?'✅ WON':r.status==='LOSS'?'❌ LOSS':r.status==='PUSH'?'🟡 PUSH':r.status==='HALF_WON'?'🟢 HALF WON':r.status==='HALF_LOST'?'🔴 HALF LOST':r.status;
  const sign=r.pnl>0?'+':'';
  out.push({json:{
    settlementRun:true,settled:true,pick_id:p.id,fixture_id:fid,home_team:p.home_team,away_team:p.away_team,
    status:r.status,pnl:r.pnl,return_amount:ret,home_score:Number(h),away_score:Number(a),
    telegram_chat_id:p.telegram_chat_id||'-1003038027412',telegram_message_id:p.telegram_message_id||null,
    replyReady:ready,settlement_reply_status:(ready?'PENDING':'NOT_APPLICABLE'),reply_text:`${label} · ${h}:${a} · P/L ${sign}${r.pnl.toFixed(2)} €`
  }});
}


// Recover crashed Telegram sends. A SENDING claim older than 20 minutes is
// returned to PENDING before the queue is read.
const staleCutoff=new Date(Date.now()-20*60*1000).toISOString();
await req.call(this,{
  method:'PATCH',
  url:`${SUPABASE_URL.replace(/\/$/,'')}/rest/v1/sr_fusion_engine_picks?settlement_reply_status=eq.SENDING&reply_claimed_at=lt.${encodeURIComponent(staleCutoff)}&reply_sent=eq.false`,
  headers:{...sbHeaders,Prefer:'return=minimal'},
  body:{settlement_reply_status:'PENDING',reply_claimed_at:null,reply_claim_token:null},
  json:true
});

// Recovery queue: any already-settled published pick whose Telegram reply has not been confirmed.
// This is deliberately independent from OPEN settlement so a Telegram failure never loses the reply.
const pendingRes=await req.call(this,{
  method:'GET',
  url:`${SUPABASE_URL.replace(/\/$/,'')}/rest/v1/sr_fusion_engine_picks?settlement_status=in.(WON,LOSS,PUSH,HALF_WON,HALF_LOST,VOID)&telegram_message_id=not.is.null&settlement_reply_status=in.(PENDING,FAILED)&select=*&order=settled_at.asc`,
  headers:sbHeaders,json:true
});
let recoveryQueued=0;
if(pendingRes.ok){
  const pending=Array.isArray(pendingRes.body)?pendingRes.body:[];
  const already=new Set(out.filter(x=>x?.json?.replyReady).map(x=>Number(x.json.pick_id)));
  for(const p of pending){
    if(already.has(Number(p.id))) continue;
    const st=String(p.settlement_status||'').toUpperCase();
    const label=st==='WON'?'✅ WON':st==='LOSS'?'❌ LOSS':st==='PUSH'?'🟡 PUSH':st==='HALF_WON'?'🟢 HALF WON':st==='HALF_LOST'?'🔴 HALF LOST':st==='VOID'?'⚪ VOID':st;
    const hs=Number.isFinite(Number(p.home_score))?Number(p.home_score):null;
    const as=Number.isFinite(Number(p.away_score))?Number(p.away_score):null;
    const score=(hs!==null&&as!==null)?`${hs}:${as}`:'—';
    const pnl=Number(p.pnl||0), sign=pnl>0?'+':'';
    out.push({json:{
      settlementRun:true,recovery:true,settled:true,pick_id:p.id,fixture_id:p.fixture_id,
      home_team:p.home_team,away_team:p.away_team,status:st,pnl,
      home_score:hs,away_score:as,
      telegram_chat_id:p.telegram_chat_id||'-1003038027412',
      telegram_message_id:p.telegram_message_id,
      replyReady:true,settlement_reply_status:String(p.settlement_reply_status||'PENDING'),
      reply_text:`${label} · ${score} · P/L ${sign}${pnl.toFixed(2)} €`
    }});
    recoveryQueued++;
  }
}else{
  out.push({json:{diagnostic:true,settlementRun:true,recoveryQueryFailed:true,httpStatus:pendingRes.status||0,detail:pendingRes.error||null}});
}

if(!out.length) out.push({json:{diagnostic:true,settlementRun:true,openRows:rows.length,settled:0,repliesReady:0,reason:'NO_SETTLEMENT_OUTPUT'}});
out.push({json:{diagnostic:true,settlementSummary:true,openRows:rows.length,settled,repliesReady,recoveryQueued,providerErrors,notFinal,invalidScore,unsupported,patchErrors,observedAt:new Date().toISOString()}});
return out;

