function localDateTimeUtc(ymd,hour=0,minute=0){
  const probe=new Date(ymd+'T12:00:00Z');
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:TZ,timeZoneName:'longOffset',hour:'2-digit'}).formatToParts(probe);
  const z=parts.find(p=>p.type==='timeZoneName')?.value||'GMT+03:00';
