        if(side==='NO') s=100-s;
        // partial evidence only: lower weight because standings requirement is unavailable.
        parts.push({name:'BTTS_FILTER_PARTIAL',available:true,weight:0.05,score:clamp(s,0,100),
          evidence:{hits,total,standings_missing:true}});
        missing.push('BTTS_FILTER_STANDINGS');
      } else missing.push('BTTS_FILTER');
   }

   // D2) v1.5.1 H2H_CONTEXT — FULL at >=5; PARTIAL at 2-4 with reduced weight.
   // It is market-specific and independent from the team attack/defence sample.
   const hc=q.history_context||{};
   const hr=Array.isArray(hc.h2h_results)?hc.h2h_results:[];
   if(hr.length>=2){
     let evidenceSum=0,total=0,hits=0;
     const splitHistLine=L=>{const ql=Math.round(Number(L)*4)/4;return Math.abs(ql*2-Math.round(ql*2))>1e-9?[Math.floor(ql*2)/2,Math.ceil(ql*2)/2]:[ql];};
     const histLeg=v=>v>1e-12?1:v<-1e-12?-1:0;
     for(const r of hr){
       const hg=Number(r.home_goals),ag=Number(r.away_goals);
       if(!finite(hg)||!finite(ag))continue;
       let value=null;
       if(fam==='BTTS'){
         const yes=hg>0&&ag>0; value=((side==='YES')===yes)?1:-1;
       } else if(fam==='GOALS' && finite(line)){
         const tg=hg+ag, legs=splitHistLine(line);
         value=legs.reduce((s,L)=>s+histLeg(side==='OVER'?tg-L:L-tg),0)/legs.length;
       } else if(fam==='MONEYLINE'){
         const homeId=Number(r.home_id),awayId=Number(r.away_id);
         const curHomeId=Number(q.home_team_id||x.home_team_id||0),curAwayId=Number(q.away_team_id||x.away_team_id||0);
         let ch=null,ca=null;
         if(homeId===curHomeId&&awayId===curAwayId){ch=hg;ca=ag;}
         else if(homeId===curAwayId&&awayId===curHomeId){ch=ag;ca=hg;}
         if(ch!=null){const ok=side==='HOME'?ch>ca:side==='AWAY'?ca>ch:ch===ca;value=ok?1:-1;}
       }
       if(value!==null){total++;evidenceSum+=value;if(value>0)hits++;}
     }
     if(total>=2){
       const avgResult=evidenceSum/total, hw=total>=5?0.10:0.04;
       parts.push({name:'H2H_CONTEXT',available:true,weight:hw,score:clamp(50+avgResult*50,0,100),
         evidence:{matches:total,positive_results:hits,average_settlement_result:avgResult,tier:total>=5?'FULL':'PARTIAL',full_weight_min:5,asian_settlement_aware:fam==='GOALS'}});
     } else missing.push('H2H_CONTEXT_MARKET_MAPPING');
   } else missing.push('H2H_CONTEXT');

   // E) v1.4.2: VALUE IS NOT PART OF THE FUSION SCORE.
   // calibrated_ev / calibrated_edge_pp are intentionally excluded here.
   // This prevents the later value gate from validating EV with a score that already contains EV.

   // Unsupported prompt inputs remain explicit missing data; no synthetic scores.
   for(const z of ['INJURIES','WEATHER','PLAYER_IMPACT','LIVE_DMI','COHESION','STYLE_MATCHUP','MOTIVATION'])
      missing.push(z);

   const w=parts.reduce((s,p)=>s+p.weight,0);
   const fusionScore=w?parts.reduce((s,p)=>s+p.weight*p.score,0)/w:0;

   // v1.4.3 EVIDENCE-AWARE FUSION:
   // Availability is not the same as independent confirmation.
   // Scores in the neutral band [45,55] remain in Fusion Score/diagnostics,
   // but do NOT count as directional evidence.
   const sourceCount=parts.length;
   const confirmingParts=parts.filter(p=>Number(p.score)>55);
   const opposingParts=parts.filter(p=>Number(p.score)<45);
   const neutralParts=parts.filter(p=>Number(p.score)>=45 && Number(p.score)<=55);
   const confirmingCount=confirmingParts.length;
   const directionalCount=confirmingParts.length+opposingParts.length;
   const confirmingWeight=confirmingParts.reduce((s,p)=>s+Number(p.weight||0),0);

   // Require at least one genuinely confirming component in addition to the
   // overall Fusion threshold. Do not fabricate a 3-source confirmation from
   // neutral 50-ish components. EV/value remains a separate downstream gate.
   const evidenceFamilyOf=(name)=>{
     if(['POISSON_DC_CALIBRATED','GPM_ATTACK_DEFENCE','RESULT_LAMBDA_BALANCE'].includes(name))return 'MODEL_CORE';
     if(['IPT_60_40','VENUE_FORM_RESULT'].includes(name))return 'TEAM_HISTORY';
     if(name==='H2H_CONTEXT')return 'H2H_CONTEXT';
     if(name==='BTTS_FILTER_PARTIAL')return 'MARKET_STRUCTURE';
     return name;
   };
   const confirmingFamilies=[...new Set(confirmingParts.map(p=>evidenceFamilyOf(p.name)))];
   const availableFamilies=[...new Set(parts.map(p=>evidenceFamilyOf(p.name)))];
   const evidencePassed=confirmingFamilies.length>=2 || (confirmingFamilies.length>=1 && confirmingWeight>=0.50);
   const q2={...q,
     fusion_score:fusionScore,
     fusion_source_count:sourceCount,
     fusion_confirming_count:confirmingCount,
     fusion_confirming_family_count:confirmingFamilies.length,
     fusion_confirming_families:confirmingFamilies,
     fusion_available_families:availableFamilies,
     fusion_directional_count:directionalCount,
     fusion_confirming_weight:confirmingWeight,
     fusion_neutral_count:neutralParts.length,
     fusion_opposing_count:opposingParts.length,
     fusion_components:parts.map(p=>({...p,
       evidence_class:Number(p.score)>55?'CONFIRMING':(Number(p.score)<45?'OPPOSING':'NEUTRAL')
     })),
     fusion_missing_inputs:[...new Set(missing)],
     fusion_evidence_passed:evidencePassed,
     fusion_passed:sourceCount>=3 && fusionScore>=60 && evidencePassed
   };
   scored.push(q2);
 }
 const passed=scored.filter(q=>q.fusion_passed===true).map(q=>{
   const prior=finite(q.market_score)?Number(q.market_score):50;
   return {...q,
     pre_fusion_market_score:prior,
     market_score:0.55*Number(q.fusion_score||0)+0.45*prior
   };
 });
 out.push({json:{...x,candidates:passed,
   fusionRawInput:raw.length,
   fusionExcludedFamily:raw.length-arr.length,
   fusionInput:arr.length,
   fusionPassed:passed.length,
   fusionRejected:{LOW_SCORE:scored.filter(q=>q.fusion_source_count>=3&&q.fusion_score<60).length,
                   INSUFFICIENT_SOURCES:scored.filter(q=>q.fusion_source_count<3).length,
                   NO_CONFIRMING_EVIDENCE:scored.filter(q=>q.fusion_source_count>=3&&q.fusion_score>=60&&!q.fusion_evidence_passed).length},
   fusionAudit:scored.map(q=>({
      market_family:q.market_family,market_key:q.market_key,side:q.side,line:q.line,
      odd:q.odd,fusion_score:q.fusion_score,fusion_source_count:q.fusion_source_count,
      fusion_confirming_count:q.fusion_confirming_count,fusion_neutral_count:q.fusion_neutral_count,
      fusion_opposing_count:q.fusion_opposing_count,fusion_evidence_passed:q.fusion_evidence_passed,
      fusion_passed:q.fusion_passed,pre_fusion_market_score:Number(q.market_score||0)
   }))
 }});
}
return out;

const SUPABASE_URL=$env.SUPABASE_URL || 'https://nhgqksizfyumdqmuuznx.supabase.co';
const SUPABASE_KEY=$env.SUPABASE_SERVICE_KEY || 'SET_SUPABASE_SECRET_IN_N8N_ENV';
if(!SUPABASE_URL||!SUPABASE_KEY) throw new Error('MISSING_SUPABASE_CONFIG');
const end=new Date(), start=new Date(end.getTime()-24*60*60*1000);
const url=SUPABASE_URL.replace(/\/$/,'')+'/rest/v1/sr_fusion_engine_funnel_runs?observed_at=gte.'+encodeURIComponent(start.toISOString())+'&observed_at=lt.'+encodeURIComponent(end.toISOString())+'&select=fixture_id,publish,final_reason,diagnostics,observed_at';
const r=await this.helpers.httpRequest({method:'GET',url,headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`},json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:20000});
if(Number(r.statusCode||0)<200||Number(r.statusCode||0)>=300) throw new Error('FUNNEL_REPORT_HTTP_'+r.statusCode);
const rows=Array.isArray(r.body)?r.body:[];
const by=new Map();
for(const row of rows){const k=String(row.fixture_id??'NULL_'+row.observed_at); const prev=by.get(k); if(!prev||String(row.observed_at)>String(prev.observed_at))by.set(k,row)}
const u=[...by.values()];
const max=(fn)=>u.reduce((s,x)=>s+(fn(x)?1:0),0);
const stage=(k)=>max(x=>Number(x?.diagnostics?.[k]||0)>0);
const reasons={}; for(const x of u){if(x.publish)continue;const z=x.final_reason||'UNKNOWN';reasons[z]=(reasons[z]||0)+1}
const top=Object.entries(reasons).sort((a,b)=>b[1]-a[1]).slice(0,6);
const discovered=Math.max(0,...u.map(x=>Number(x?.diagnostics?.discovery?.fixtures_fetched||0)));
const watched=Math.max(0,...u.map(x=>Number(x?.diagnostics?.discovery?.fixtures_in_watch_window||0)));
const published=max(x=>x.publish===true);
const lines=['📊 FUSION ENGINE · DAILY FUNNEL · 24H','',`🌍 Discovery max/run: ${discovered}`,`🎯 Watch-window max/run: ${watched}`,`⚽ Unique analysed fixtures: ${u.length}`,`📈 With normalized markets: ${stage('marketsNormalized')}`,`⏱ T20–T50 passed: ${stage('t30Passed')}`,`💰 Odds gate passed: ${stage('oddsPassed')}`,`🧮 Calibration passed: ${stage('calibrationPassed')}`,`🧱 Quality passed: ${stage('qualityPassed')}`,`🧬 Fusion passed: ${stage('fusionPassed')}`,`💎 Fusion value passed: ${stage('fusionValuePassed')}`,`📣 Published: ${published}`,'','Top no-signal reasons:',...(top.length?top.map(([k,v])=>`• ${k}: ${v}`):['• none'])];
return [{json:{report_text:lines.join('\n'),rows:rows.length,unique_fixtures:u.length}}];

parameters.content:
## FUSION ENGINE v1.3.2 · DIAGNOSTIC FUNNEL

Diagnostic/observability release. Prediction thresholds are unchanged from v1.3.1.

Added:
- Bet365 response/market/candidate diagnostics in Node 02;
- exact terminal no-signal reason instead of generic NO_T30_SIGNAL;
- discovery metadata propagated into funnel diagnostics;
- daily rolling-24h funnel report at 06:25 to the test Telegram channel;
- friendlies/international matches remain eligible and are measured by league.

No SQL migration required: extended diagnostics are stored in the existing JSONB diagnostics field.

