// Independent research side branch. Does not change the main publication path.
const src=$json||{};
const h=src.ht_research||{};
if(!h.market_present||![0.5,1.5].includes(Number(h.line))||!(Number(h.over_odd)>1))
 return {research_saved:false,reason:!h.market_present?'NO_HT_MARKET':'NO_SUPPORTED_HT_OVER_PRICE',fixture_id:src.fixture_id};
const base=$env.SUPABASE_URL || 'https://nhgqksizfyumdqmuuznx.supabase.co';
const key=$env.SUPABASE_SERVICE_KEY || 'SET_SUPABASE_SECRET_IN_N8N_ENV';
if(!base||!key)return {research_saved:false,reason:'SUPABASE_ENV_NOT_SET',fixture_id:src.fixture_id};
const record={fixture_id:Number(src.fixture_id),kickoff:src.kickoff,home_team:src.home_team,away_team:src.away_team,league:src.league,
 market_family:'FIRST_HALF_GOALS',market_key:`HT_OVER_${Number(h.line)}`,side:'OVER',line:Number(h.line),odd:Number(h.over_odd),
 opening_odd:h.opening_over_odd??null,source:'BET365',model_status:'PENDING_VERIFIED_HT_HISTORY',
 snapshot_at:new Date().toISOString(),raw_market:h};
if(!Number.isFinite(record.fixture_id)||!record.kickoff)return {research_saved:false,reason:'INVALID_FIXTURE',fixture_id:src.fixture_id};
try{
 await this.helpers.httpRequest({method:'POST',url:base.replace(/\/$/,'')+'/rest/v1/sr_fusion_ht_research?on_conflict=fixture_id%2Cmarket_key',
 headers:{apikey:key,Authorization:`Bearer ${key}`,Prefer:'resolution=ignore-duplicates,return=minimal','Content-Type':'application/json'},
 body:record,json:true,ignoreHttpStatusErrors:false,timeout:12000});
 return {research_saved:true,fixture_id:record.fixture_id,market_key:record.market_key,odd:record.odd,research_only:true};
}catch(e){return {research_saved:false,reason:'DB_WRITE_FAILED',error:String(e.message||e).slice(0,220),fixture_id:src.fixture_id};}
